r.append(R(7675617,"ग्रिल की हुई भूमध्यसागरीय शिमला मिर्च",
"ये जीवंत भरवाँ शिमला मिर्चें ताज़े स्वादों से भरपूर हैं।",
"6","186 ग्राम",
["3 बड़ी लाल शिमला मिर्च","450 ग्राम/16 औंस मिले-जुले चेरी टमाटर, जैसे सुनहरे, पीले और लाल, आधे कटे हुए","1 शैलट (छोटा प्याज़), बारीक कटा हुआ","4 फांक लहसुन, पतला कटा हुआ","2 बड़े चम्मच तुलसी की पत्तियाँ, बारीक कटी हुई, सजाने के लिए थोड़ी और","2 छोटे चम्मच जैतून का तेल","ताज़ा पिसी हुई काली मिर्च"],
["ग्रिल को तेज़ आँच पर पहले से गरम करें। एक किनारे वाली बेकिंग ट्रे पर वायर रैक रखें।","शिमला मिर्च को आधा काटें और सफ़ेद नसें और बीज निकालकर फेंक दें।","एक मिक्सिंग बाउल में आधे कटे चेरी टमाटर, कटा हुआ शैलट, कटा हुआ लहसुन, कटी हुई तुलसी और जैतून का तेल मिलाएँ। स्वादानुसार ताज़ी पिसी काली मिर्च डालें।","टमाटर के सलाद को शिमला मिर्च के आधे हिस्सों में बाँट दें और उन्हें ट्रे पर वायर रैक पर सजा दें।","लगभग 4-5 मिनट तक ग्रिल करें, जब तक शिमला मिर्च के किनारे हल्के जल न जाएँ।","ग्रिल से निकालें और परोसने से पहले थोड़ी देर रहने दें, फिर तुलसी की पत्तियों से सजाकर थाली में परोसें।"],
["टमाटर के मिश्रण में आधी बारीक कटी मिर्च डालकर इस व्यंजन को मसालेदार बनाएँ।",FV(2)]))
r.append(R(7677354,"भरवाँ पराँठे",
"छोटे आकार के शाकाहारी पराँठे आम पार्टी के खाने में एक अनोखा अंदाज़ जोड़ते हैं।",
"16","40 ग्राम",
[["भरावन के लिए","1 बड़ा शकरकंद (लगभग 350 ग्राम), छिला और चार भागों में कटा हुआ"],["भरावन के लिए","4 हरे प्याज़, कटे हुए"],["भरावन के लिए","1 छोटा चम्मच पिसी हल्दी"],["भरावन के लिए","1 छोटा चम्मच पिसा जीरा"],["भरावन के लिए","1 छोटा चम्मच पिसा धनिया"],["भरावन के लिए","2 फांक लहसुन, कुचला हुआ"],["भरावन के लिए","½ लाल मिर्च, बारीक कटी हुई"],["भरावन के लिए","25 ग्राम ताज़ा धनिया, कटा हुआ"],["भरावन के लिए","50 ग्राम जमे हुए मटर, पिघलाए हुए"],
["आटे के लिए","200 ग्राम साबुत गेहूँ का आटा"],["आटे के लिए","½ छोटा चम्मच बेकिंग पाउडर"],["आटे के लिए","100 ग्राम 0% फ़ैट वाला दही"],["आटे के लिए","125 मिली पानी"],["आटे के लिए","2 छोटे चम्मच रेपसीड तेल"]],
["शकरकंद को 10–15 मिनट तक नरम होने तक उबालें, फिर पानी निथारकर मैश कर लें।","शकरकंद में हरे प्याज़, हल्दी, जीरा, पिसा धनिया, लहसुन और मिर्च, ताज़ा धनिया और मटर डालें। अच्छी तरह मिलाकर अलग रख दें।","एक कटोरे में आटा, बेकिंग पाउडर, दही और पानी डालें। अच्छी तरह मिलाकर आटा गूँध लें।","आटे को 8 गोलों में बाँटें। हल्के आटे लगी सतह पर हर गोले को पतले गोलों में बेल लें, जिससे 8 रोटियाँ बनेंगी।","भरावन को चार भागों में बाँटें और उसे चार आटे के गोलों पर फैला दें, किनारे के चारों ओर 1 सेमी का हिस्सा छोड़ दें।","किनारों पर थोड़ा पानी लगाएँ, फिर ऊपर से आटे का एक और गोला रखें और किनारों को मज़बूती से दबाकर जोड़ दें।","नॉन-स्टिक फ्राइंग पैन पर ½ छोटा चम्मच तेल लगाएँ, फिर एक पराँठा पैन में रखें और धीमी से मध्यम आँच पर 2 मिनट तक पकाएँ, स्पैचुला से पलटें और दूसरी तरफ़ 2 मिनट पकाएँ। फिर से पलटें और हर तरफ़ एक मिनट और पकाएँ। (तैयार होने पर पराँठे की सतह पर कुछ भूरे धब्बे होने चाहिए)। बचे हुए पराँठों के साथ इसे दोहराएँ।","परोसने के लिए चार टुकड़ों में काट लें।"],
["भरावन मिलाते समय उसमें कुछ कटी हुई ताज़ी मिर्च और कद्दूकस किया हुआ अदरक डालकर इन पराँठों को और मसालेदार बनाया जा सकता है।",FV(1)]))
r.append(R(7681544,"सेब और किशमिश के चेल्सी बन",
"ये चिपचिपे, ख़ुशबूदार बन दोपहर में ताज़गी पाने के लिए एकदम सही हैं।",
"16","66 ग्राम",
["250 ग्राम साबुत गेहूँ का आटा","200 ग्राम मैदा","20 ग्राम बारीक चीनी","7 ग्राम का सैशे फ़ास्ट-एक्टिंग यीस्ट","50 मिली रेपसीड तेल (कटोरे और बेकिंग शीट पर लगाने के लिए 2 छोटे चम्मच अलग रखें)","1 अंडा, फेंटा हुआ","200 मिली सेमी-स्किम्ड दूध, गुनगुना किया हुआ (बन पर लगाने के लिए थोड़ा-सा अलग रखें)","1 छोटा चम्मच शहद",
["भरावन के लिए","2 मीठे सेब, छिले, बीज निकाले और मोटे कटे हुए"],["भरावन के लिए","1 बड़ा चम्मच पानी"],["भरावन के लिए","2 ढेर वाले छोटे चम्मच पिसी दालचीनी"],["भरावन के लिए","2–3 छोटे चम्मच दानेदार स्वीटनर"],["भरावन के लिए","70 ग्राम किशमिश"]],
["साबुत गेहूँ का आटा और मैदा चीनी और यीस्ट के साथ मिलाएँ। बीच में गड्ढा बना लें।","तेल, अंडा और आधा दूध डालें। अच्छी तरह मिलाएँ, धीरे-धीरे बाक़ी दूध डालते रहें जब तक कि आटा न बन जाए।","आटे को आटे लगी सतह पर निकालें और पाँच मिनट तक गूँधें जब तक वह लचीला न हो जाए। तेल लगे कटोरे में रखें, क्लिंग फ़िल्म से ढकें और दोगुना होने के लिए 1 घंटे तक गरम जगह पर छोड़ दें।","इस बीच, भरावन बनाएँ: सेब को पानी के साथ पैन में डालें, ढक दें और धीमी से मध्यम आँच पर 10 मिनट तक पकाएँ, बीच-बीच में काँटे से मसलते रहें जब तक कि वे नरम गूदा न बन जाएँ। आँच से उतारें और दालचीनी, स्वीटनर और किशमिश डालें। अच्छी तरह मिलाएँ, ढक दें और ठंडा होने दें।","आटे को उसके मूल आकार में लाकर 'नॉक बैक' करें (हवा निकालें), फिर हल्के आटे लगी सतह पर निकालें। ½ सेमी मोटे आयताकार आकार में बेल लें (लगभग 48x30 सेमी)।","सेब/किशमिश का मिश्रण आटे पर फैलाएँ, सबसे लंबे ऊपरी किनारे पर 2–3 सेमी का हिस्सा खाली छोड़ दें।","आटे को कसकर बेलन के आकार में लपेटें, जोड़ तली की तरफ़ रखें, फिर इसे लगभग 3 सेमी मोटे 16 टुकड़ों में काट लें।","बन को हल्के तेल लगी बेकिंग शीट पर रखें, किचन टॉवल से ढकें और 30 मिनट और फूलने के लिए छोड़ दें। इस बीच ओवन को 180°C/गैस 4 पर पहले से गरम करें।","बन पर दूध लगाएँ और 20–25 मिनट तक फूलने और सुनहरा होने तक बेक करें। ओवन से निकालें, शहद लगाएँ और ठंडा होने दें।"],
["आप किशमिश (सुल्ताना), करेंट या सूखे फलों का मिश्रण इस्तेमाल कर सकते हैं।","भरावन में थोड़ा कद्दूकस किया हुआ नींबू या संतरे का छिलका डालकर देखें, या दालचीनी की जगह मिक्स्ड स्पाइस का उपयोग करें।"]))
r.append(R(7682200,"साग आलू",
"स्वादिष्ट और पौष्टिक, यह शाकाहारी पारिवारिक पसंदीदा व्यंजन स्वाद से भरपूर है। ब्लाइथ परिवार द्वारा भेजा गया",
"4","512 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","1 हरी शिमला मिर्च, बारीक कटी हुई","2 बड़ी गाजर, मोटी कटी हुई","1 सेमी अदरक का टुकड़ा, छिला और बारीक कटा हुआ","2 बड़े आलू (लगभग 600 ग्राम), मोटे कटे हुए","1–2 ताज़ी हरी मिर्च, बीज निकालकर बारीक कटी हुई (½ मिर्च = हल्का, 1 = मध्यम, 2 = तीखा)","एक गुच्छा ताज़ा धनिया, बारीक कटा हुआ","500 ग्राम ताज़ा पालक","500 मिली कम नमक वाला वेजिटेबल स्टॉक","1 छोटा चम्मच जीरा","1 छोटा चम्मच पिसा धनिया","1 छोटा चम्मच हल्दी","1 छोटा चम्मच पिसी मेथी","1 छोटा चम्मच स्मोक्ड पेपरिका","1 छोटा चम्मच गरम मसाला","या, 1 बड़ा चम्मच तंदूरी करी पाउडर इस्तेमाल करें"],
["एक बड़े पैन में तेल डालें, प्याज़ और शिमला मिर्च को बीच-बीच में चलाते हुए 3–4 मिनट तक नरम होने तक भूनें।","गाजर और अदरक डालें और बीच-बीच में चलाते हुए पाँच मिनट पकाएँ। सब कुछ पैन से निकालकर एक तरफ़ रख दें।","उसी पैन में आलू डालें और बीच-बीच में चलाते हुए 5 मिनट पकाएँ। प्याज़, शिमला मिर्च, अदरक और गाजर को वापस पैन में डालें।","मसाले और हरी मिर्च डालें (मात्रा इस पर निर्भर करती है कि आपको कितना तीखा पसंद है!) और 3 मिनट तक पकाएँ, जब तक मसाले चिपकने न लगें।","स्टॉक डालें और गाढ़ा होने तक 20 मिनट धीमी आँच पर पकाएँ।","ताज़ा धनिया और आधा पालक डालकर 3 मिनट पकाएँ। जब पालक मुरझा जाए, तो बाक़ी पालक मिला दें। 1–2 मिनट और पैन में रहने दें, फिर चावल के साथ परोसें।"],
["आलू की जगह शकरकंद आज़माएँ, जिससे आपके दिन के पाँच फल-सब्ज़ी की सर्विंग में एक अतिरिक्त सर्विंग जुड़ती है।","इसे आधी कटी शिमला मिर्च (किसी भी रंग की) में भरकर, ऊपर थोड़ा-सा चीज़ डालकर 180°C/गैस 4 पर 15-20 मिनट तक, ऊपर से सुनहरा भूरा होने तक, बेक करने पर बहुत बढ़िया लगता है।","एक सेहतमंद रैप के लिए इसे सलाद और खीरे के रायते के साथ रोटी या चपाती में लपेटकर आज़माएँ।",FV(3)]))
r.append(R(7683555,"कीमा बीफ़ और सब्ज़ियों की फ़िलो पाई",
"कुरकुरी फ़िलो परत वाला एक पेट भरने वाला, गरमाहट देने वाला और पौष्टिक व्यंजन।",
"4","275 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","1 प्याज़, चौकोर कटा हुआ","100 ग्राम मशरूम, कटे हुए","250 ग्राम लीन कीमा बीफ़","1 गाजर, छोटे चौकोर टुकड़ों में कटी हुई","150 ग्राम शकरकंद, छिला और छोटे टुकड़ों में कटा हुआ","2 छोटे चम्मच मैदा","1 छोटा चम्मच टमाटर प्यूरी","एक अच्छी चुटकी सफ़ेद मिर्च","एक चुटकी सूखा थाइम","1 कम नमक वाला बीफ़ स्टॉक क्यूब, 300 मिली पानी में घुला हुआ","75 ग्राम जमे हुए मटर, पिघलाए हुए","2 छिड़काव रेपसीड तेल","150 ग्राम फ़िलो पेस्ट्री (लगभग 3 शीट)"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। एक सॉसपैन में तेल गरम करें, प्याज़ डालें और हल्का भूरा होने तक चलाएँ।","मशरूम और कीमा बीफ़ डालें और 4-5 मिनट तक चलाएँ, लकड़ी के चम्मच से मांस की किसी भी गाँठ को तोड़ते रहें।","कटी हुई गाजर और शकरकंद डालें, मैदा छिड़कें और अच्छी तरह मिलाएँ। टमाटर प्यूरी, मिर्च और थाइम मिला दें।","स्टॉक मिलाएँ, उबाल आने दें, पैन के ढक्कन से ढकें, आँच कम करें और गाजर के नरम होने तक 12-15 मिनट धीमी आँच पर पकाएँ। मटर डालें, चलाएँ और मिश्रण को ओवन-सुरक्षित डिश में रखें।","फ़िलो शीट पर थोड़ा तेल स्प्रे करें और बीफ़ के मिश्रण के ऊपर हल्की-सी 'सिकोड़ी' हुई परतें रखें।","10 मिनट तक बेक करें, जब तक पेस्ट्री हल्की भूरी न हो जाए। भाप में पकी गाजर, मक्का और ब्रोकली के साथ परोसें।"],
["आप इस व्यंजन के लिए टर्की जैसे किसी भी कीमे, या मांस के विकल्प (जैसे सोया) का उपयोग कर सकते हैं।","ग्लूटेन-मुक्त संस्करण के लिए सॉस को गाढ़ा करने के लिए ग्लूटेन-मुक्त आटा इस्तेमाल करें और फ़िलो की जगह ऊपर से बहुत पतले कटे शकरकंद डालें। आपको पकाने का समय 15 मिनट तक बढ़ाना होगा।",FV(2)]))
